import React, { useState, useEffect } from 'react';
import { getEntrenamientos, getAsistenciaEntrenamientos, toggleApuntarseEntrenamiento, getCurrentUser } from '../../database/db';
import './MisEntrenamientos.css';

function MisEntrenamientos() {
  const [entrenamientos, setEntrenamientos] = useState([]);
  const [asistencia, setAsistencia] = useState([]);
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    cargarDatos();
  }, []);

  const cargarDatos = async () => {
    setLoading(true);
    try {
      const currentUser = getCurrentUser();
      setUser(currentUser);
      
      const [entrenamientosData, asistenciaData] = await Promise.all([
        getEntrenamientos(),
        getAsistenciaEntrenamientos()
      ]);
      
      setEntrenamientos(entrenamientosData || []);
      setAsistencia(asistenciaData || []);
      console.log('Entrenamientos cargados:', entrenamientosData);
    } catch (error) {
      console.error('Error cargando datos:', error);
      alert('Error al cargar los entrenamientos');
    } finally {
      setLoading(false);
    }
  };

  const handleApuntarse = async (entrenamientoId, currentEstado) => {
    try {
      // Si ya está apuntado, desapuntar; si no, apuntarse
      const nuevoEstado = currentEstado === 'apuntado' ? 'no_apuntado' : 'apuntado';
      await toggleApuntarseEntrenamiento(entrenamientoId, user.id);
      await cargarDatos();
      
      if (nuevoEstado === 'apuntado') {
        alert('✅ Te has apuntado al entrenamiento');
      } else {
        alert('❌ Has cancelado tu apunte');
      }
    } catch (error) {
      alert('Error al actualizar: ' + error.message);
    }
  };

  const getMiEstado = (entrenamientoId) => {
    const registro = asistencia.find(a => a.entrenamiento_id === entrenamientoId && a.jugador_id === user?.id);
    return registro?.estado || 'no_apuntado';
  };

  const getEstadoInfo = (estado) => {
    const estados = {
      'apuntado': { 
        text: '📋 Apuntado', 
        class: 'estado-apuntado', 
        accion: 'Cancelar apunte',
        botonClass: 'btn-cancelar'
      },
      'asistio': { 
        text: '✅ Asististe', 
        class: 'estado-asistio', 
        accion: null,
        botonClass: ''
      },
      'falta': { 
        text: '❌ No asististe', 
        class: 'estado-falta', 
        accion: null,
        botonClass: ''
      },
      'no_apuntado': { 
        text: '⭕ No apuntado', 
        class: 'estado-no', 
        accion: 'Apuntarme',
        botonClass: 'btn-apuntarse'
      }
    };
    return estados[estado] || estados.no_apuntado;
  };

  const formatearFecha = (fecha) => {
    if (!fecha) return null;
    try {
      const fechaObj = new Date(fecha);
      if (!isNaN(fechaObj.getTime())) {
        return fechaObj;
      }
      return null;
    } catch (e) {
      return null;
    }
  };

  const formatearHora = (hora) => {
    if (!hora) return 'Hora no disponible';
    try {
      // Si hora viene en formato "HH:MM:SS" o "HH:MM"
      const partes = hora.split(':');
      if (partes.length >= 2) {
        return `${partes[0]}:${partes[1]}`;
      }
      return hora;
    } catch (e) {
      return hora;
    }
  };

  // Filtrar entrenamientos
  const hoy = new Date();
  hoy.setHours(0, 0, 0, 0);
  
  const entrenamientosFuturos = entrenamientos.filter(e => {
    const fechaObj = formatearFecha(e.fecha);
    return fechaObj && fechaObj >= hoy;
  }).sort((a, b) => new Date(a.fecha) - new Date(b.fecha));
  
  const entrenamientosPasados = entrenamientos.filter(e => {
    const fechaObj = formatearFecha(e.fecha);
    return fechaObj && fechaObj < hoy;
  }).sort((a, b) => new Date(b.fecha) - new Date(a.fecha));

  if (loading) {
    return (
      <div className="mis-entrenamientos">
        <div className="loading-container">
          <i className="fas fa-spinner fa-spin"></i>
          <p>Cargando entrenamientos...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="mis-entrenamientos">
      <div className="header-mis-entrenamientos">
        <h2><i className="fas fa-futbol"></i> Mis Entrenamientos</h2>
        <p className="subtitle">Apúntate a los entrenamientos y registra tu asistencia</p>
      </div>

      {/* Próximos entrenamientos */}
      <div className="seccion-entrenamientos">
        <div className="seccion-header">
          <h3><i className="fas fa-calendar-alt"></i> Próximos Entrenamientos</h3>
          <span className="contador">{entrenamientosFuturos.length} programados</span>
        </div>
        
        {entrenamientosFuturos.length === 0 ? (
          <div className="empty-state">
            <i className="fas fa-calendar-check"></i>
            <p>No hay entrenamientos programados próximamente</p>
          </div>
        ) : (
          <div className="entrenamientos-grid">
            {entrenamientosFuturos.map(ent => {
              const estado = getMiEstado(ent.id);
              const estadoInfo = getEstadoInfo(estado);
              const fechaObj = formatearFecha(ent.fecha);
              
              return (
                <div key={ent.id} className="entrenamiento-card-jugador">
                  <div className="fecha-destacada">
                    <span className="dia">{fechaObj ? fechaObj.getDate() : '?'}</span>
                    <span className="mes">{fechaObj ? fechaObj.toLocaleString('es', { month: 'short' }) : '???'}</span>
                  </div>
                  <div className="info-entrenamiento">
                    <h4>{fechaObj ? fechaObj.toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long' }) : 'Fecha no disponible'}</h4>
                    <p><i className="fas fa-clock"></i> {formatearHora(ent.hora)} hrs</p>
                    <p><i className="fas fa-map-marker-alt"></i> {ent.lugar}</p>
                    {ent.duracion && (
                      <p><i className="fas fa-hourglass-half"></i> Duración: {ent.duracion}</p>
                    )}
                    {ent.objetivo && (
                      <p className="objetivo"><i className="fas fa-bullseye"></i> {ent.objetivo.length > 80 ? ent.objetivo.substring(0, 80) + '...' : ent.objetivo}</p>
                    )}
                    {ent.monto_pago > 0 && (
                      <p className="monto"><i className="fas fa-dollar-sign"></i> Monto: ${ent.monto_pago}</p>
                    )}
                  </div>
                  <div className="accion-entrenamiento">
                    <span className={`estado-badge ${estadoInfo.class}`}>{estadoInfo.text}</span>
                    {estadoInfo.accion && (
                      <button 
                        onClick={() => handleApuntarse(ent.id, estado)} 
                        className={estadoInfo.botonClass}
                      >
                        {estadoInfo.accion}
                      </button>
                    )}
                    {estado === 'asistio' && (
                      <span className="check-asistencia">✓ Asistencia registrada</span>
                    )}
                    {estado === 'falta' && (
                      <span className="falta-registrada">✗ Falta registrada</span>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Historial */}
      {entrenamientosPasados.length > 0 && (
        <div className="seccion-entrenamientos historial">
          <div className="seccion-header">
            <h3><i className="fas fa-history"></i> Historial de Entrenamientos</h3>
            <span className="contador">{entrenamientosPasados.length} entrenamientos</span>
          </div>
          <div className="historial-grid">
            {entrenamientosPasados.map(ent => {
              const estado = getMiEstado(ent.id);
              const estadoInfo = getEstadoInfo(estado);
              const fechaObj = formatearFecha(ent.fecha);
              
              return (
                <div key={ent.id} className="historial-card">
                  <div className="fecha-historial">
                    <i className="fas fa-calendar"></i>
                    <span>{fechaObj ? fechaObj.toLocaleDateString() : 'Fecha no disponible'}</span>
                  </div>
                  <div className="info-historial">
                    <span className="lugar-historial">{ent.lugar}</span>
                    <span className={`estado-small ${estadoInfo.class}`}>{estadoInfo.text}</span>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {entrenamientos.length === 0 && !loading && (
        <div className="empty-state-total">
          <i className="fas fa-futbol"></i>
          <p>No hay entrenamientos registrados</p>
        </div>
      )}
    </div>
  );
}

export default MisEntrenamientos;
